// src/pages/Watchlist.jsx
import React, { useContext } from 'react';
import { Link } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';
import { category } from '../api/tmdbApi';
import * as Config from "../constants/Config";
import apiConfig from '../api/apiConfig';

const Watchlist = () => {
  const { currentUser } = useContext(AuthContext);

  if (!currentUser) {
    return <div className="container mt-5 text-center"><h2>Please Sign In to view your Watchlist.</h2></div>;
  }

  const wantToWatch = currentUser.watchlist?.filter(m => m.status === 'want') || [];
  const watched = currentUser.watchlist?.filter(m => m.status === 'watched') || [];

  const renderMovieList = (movies) => {
    if (movies.length === 0) return <p style={{color: '#888'}}>No movies here yet.</p>;
    
    return (
      <div className="movie-grid">
        {movies.map(movie => (
          <Link to={`/${Config.HOME_PAGE}/${category.movie}/${movie.id}`} key={movie.id} className="movie-card">
            <img src={apiConfig.w500Image(movie.poster)} alt={movie.title} />
            <h3>{movie.title}</h3>
          </Link>
        ))}
      </div>
    );
  };

  return (
    <div className="container" style={{ paddingTop: '100px', paddingBottom: '50px' }}>
      <h1 style={{ marginBottom: '40px' }}>My Watchlist</h1>

      <div className="section mb-5">
        <h2 style={{ color: '#f5c518', borderBottom: '2px solid #f5c518', paddingBottom: '10px' }}>Want to Watch</h2>
        <br />
        {renderMovieList(wantToWatch)}
      </div>

      <div className="section">
        <h2 style={{ color: '#2ecc71', borderBottom: '2px solid #2ecc71', paddingBottom: '10px' }}>Watched</h2>
        <br />
        {renderMovieList(watched)}
      </div>
    </div>
  );
};

export default Watchlist;
